// Men's Social — Step 5: Sleep + Energy & mood check-in.
// Run from the project folder:  node setup-step-5.mjs
import { mkdirSync, writeFileSync, existsSync } from "node:fs";
import { dirname } from "node:path";

if (!existsSync("package.json") || !existsSync("src/lib/progress/calc.ts")) {
  console.error("Run this inside the Men-s-Social-True folder, after Steps 2-4 are set up.");
  process.exit(1);
}

const files = {
  "src/lib/progress/types.ts": "// The shape of every progress record in Men's Social.\n// Today these are saved on the phone; later the same shape goes into Supabase.\n\n/** Every metric the app can track. We add to this list as each tracker is built. */\nexport type MetricType = \"water\" | \"sleep\" | \"energy\" | \"mood\";\n\n/** Where a value came from — shown to the user so he knows what is real vs estimated. */\nexport type RecordSource = \"manual\" | \"quick_add\" | \"ai_estimate\" | \"device_sync\" | \"calculated\";\n\n/** ml = water, min = sleep duration, score = 1–5 self-rating */\nexport type Unit = \"ml\" | \"min\" | \"score\";\n\n/** Extra details some records carry. */\nexport interface RecordMeta {\n  bedtime?: string; // \"22:30\"\n  wakeTime?: string; // \"06:15\"\n  quality?: number; // 1–5 sleep quality\n}\n\nexport interface TrackingRecord {\n  id: string;\n  userId: string; // \"local\" until sign-up; replaced by the real account id later\n  metric: MetricType;\n  value: number;\n  unit: Unit;\n  source: RecordSource;\n  recordedAt: string; // ISO time the thing happened\n  localDate: string; // YYYY-MM-DD in the man's own timezone (used for daily totals)\n  note?: string;\n  meta?: RecordMeta;\n  createdAt: string;\n  updatedAt: string;\n}\n\nexport interface Goal {\n  metric: MetricType;\n  target: number;\n  unit: Unit;\n  period: \"day\";\n  direction: \"increase\" | \"decrease\";\n  updatedAt: string;\n}\n\n/** The three honest states a progress bar can be in. */\nexport type MetricStatus = \"not_recorded\" | \"tracked\" | \"goal_achieved\";\n\n/** Reporting periods on the Progress page (1 = today). */\nexport type Period = 1 | 7 | 30 | 90;\n",
  "src/lib/progress/calc.ts": "// All progress formulas live here, so every screen calculates the same way.\n// Rule: \"nothing recorded\" is null, never 0 — missing data must not look like zero.\n\nimport type { MetricStatus, MetricType, TrackingRecord } from \"./types\";\n\nconst isNum = (n: unknown): n is number => typeof n === \"number\" && Number.isFinite(n);\n\n/** A. Daily target progress: min(actual / target × 100, 100). */\nexport function targetProgress(actual: number | null, target: number | null): number | null {\n  if (!isNum(actual) || !isNum(target) || target <= 0) return null;\n  return Math.min(Math.max((actual / target) * 100, 0), 100);\n}\n\n/** B. Habit adherence: completed / eligible scheduled × 100. */\nexport function adherence(completed: number, eligible: number): number | null {\n  if (!isNum(completed) || !isNum(eligible) || eligible <= 0) return null;\n  return Math.min((completed / eligible) * 100, 100);\n}\n\n/** C. Measurement change: latest − baseline. */\nexport function measurementChange(latest: number | null, baseline: number | null): number | null {\n  if (!isNum(latest) || !isNum(baseline)) return null;\n  return latest - baseline;\n}\n\n/** D. Energy balance: consumed − total daily expenditure. */\nexport function energyBalance(consumed: number | null, totalExpenditure: number | null): number | null {\n  if (!isNum(consumed) || !isNum(totalExpenditure)) return null;\n  return consumed - totalExpenditure;\n}\n\n/** Tracked, goal achieved, or not yet recorded. */\nexport function metricStatus(actual: number | null, target: number | null): MetricStatus {\n  if (!isNum(actual)) return \"not_recorded\";\n  const p = targetProgress(actual, target);\n  return p !== null && p >= 100 ? \"goal_achieved\" : \"tracked\";\n}\n\n/** Total for one metric on one day — null if he recorded nothing that day. */\nexport function dayTotal(records: TrackingRecord[], metric: MetricType, key: string): number | null {\n  const day = records.filter((r) => r.metric === metric && r.localDate === key);\n  if (day.length === 0) return null;\n  return day.reduce((sum, r) => sum + r.value, 0);\n}\n\n/** Totals for many days (null where nothing was recorded). */\nexport function dayTotals(records: TrackingRecord[], metric: MetricType, keys: string[]): (number | null)[] {\n  return keys.map((k) => dayTotal(records, metric, k));\n}\n\n/** Latest record of a metric on a day (for once-a-day logs like sleep or a check-in). */\nexport function dayLatest(records: TrackingRecord[], metric: MetricType, key: string): TrackingRecord | null {\n  const day = records\n    .filter((r) => r.metric === metric && r.localDate === key)\n    .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));\n  return day[0] ?? null;\n}\n\n/** Latest value per day for many days (null where nothing was recorded). */\nexport function dayLatestValues(records: TrackingRecord[], metric: MetricType, keys: string[]): (number | null)[] {\n  return keys.map((k) => dayLatest(records, metric, k)?.value ?? null);\n}\n\n/** Sleep length in minutes from \"HH:MM\" bedtime to \"HH:MM\" wake time (crosses midnight). */\nexport function sleepMinutes(bedtime: string, wakeTime: string): number | null {\n  const parse = (t: string) => {\n    const m = /^(\\d{1,2}):(\\d{2})$/.exec(t);\n    if (!m) return null;\n    const h = Number(m[1]);\n    const min = Number(m[2]);\n    return h < 24 && min < 60 ? h * 60 + min : null;\n  };\n  const bed = parse(bedtime);\n  const wake = parse(wakeTime);\n  if (bed === null || wake === null) return null;\n  const diff = (wake - bed + 1440) % 1440;\n  return diff === 0 ? null : diff;\n}\n\n/** Change between two averages (this period vs the one before). null if either is missing. */\nexport function periodChange(current: number | null, previous: number | null): number | null {\n  if (!isNum(current) || !isNum(previous)) return null;\n  return current - previous;\n}\n\n/** Average over recorded days only — skipped days are left out, not counted as 0. */\nexport function averageRecorded(values: (number | null)[]): number | null {\n  const recorded = values.filter(isNum);\n  if (recorded.length === 0) return null;\n  return recorded.reduce((a, b) => a + b, 0) / recorded.length;\n}\n\n/** How many recorded days reached the target. */\nexport function daysGoalMet(values: (number | null)[], target: number | null): number {\n  return values.filter((v) => targetProgress(v, target) === 100).length;\n}\n\n/** Day streak: consecutive days (ending today or yesterday) where the goal was met. */\nexport function goalStreak(values: (number | null)[], target: number | null): number {\n  let i = values.length - 1;\n  // Today isn't over yet, so an unfinished today doesn't break the streak\n  if (targetProgress(values[i] ?? null, target) !== 100) i--;\n  let streak = 0;\n  for (; i >= 0; i--) {\n    if (targetProgress(values[i] ?? null, target) === 100) streak++;\n    else break;\n  }\n  return streak;\n}\n",
  "src/lib/progress/calc.test.ts": "import { describe, expect, it } from \"vitest\";\nimport {\n  adherence,\n  averageRecorded,\n  dayLatest,\n  dayTotal,\n  daysGoalMet,\n  energyBalance,\n  goalStreak,\n  measurementChange,\n  metricStatus,\n  periodChange,\n  sleepMinutes,\n  targetProgress,\n} from \"./calc\";\nimport { dateKey, lastNDays, shiftKey } from \"./dates\";\nimport type { TrackingRecord } from \"./types\";\n\nconst rec = (localDate: string, value: number): TrackingRecord => ({\n  id: `${localDate}-${value}`,\n  userId: \"local\",\n  metric: \"water\",\n  value,\n  unit: \"ml\",\n  source: \"manual\",\n  recordedAt: `${localDate}T08:00:00.000Z`,\n  localDate,\n  createdAt: \"\",\n  updatedAt: \"\",\n});\n\ndescribe(\"targetProgress\", () => {\n  it(\"matches the spec example: 1800 of 2500 ml = 72%\", () => {\n    expect(targetProgress(1800, 2500)).toBe(72);\n  });\n  it(\"caps at 100%\", () => {\n    expect(targetProgress(3000, 2500)).toBe(100);\n  });\n  it(\"returns null (not 0) when nothing is recorded or the goal is missing\", () => {\n    expect(targetProgress(null, 2500)).toBeNull();\n    expect(targetProgress(1000, 0)).toBeNull();\n    expect(targetProgress(1000, null)).toBeNull();\n  });\n});\n\ndescribe(\"other formulas\", () => {\n  it(\"adherence: 5 of 7 ≈ 71.4%\", () => {\n    expect(adherence(5, 7)).toBeCloseTo(71.43, 1);\n    expect(adherence(0, 0)).toBeNull();\n  });\n  it(\"measurement change: 87 − 90 = −3\", () => {\n    expect(measurementChange(87, 90)).toBe(-3);\n    expect(measurementChange(null, 90)).toBeNull();\n  });\n  it(\"energy balance: 2100 − 2500 = −400\", () => {\n    expect(energyBalance(2100, 2500)).toBe(-400);\n    expect(energyBalance(2100, null)).toBeNull();\n  });\n});\n\ndescribe(\"status and daily totals\", () => {\n  it(\"has three honest states\", () => {\n    expect(metricStatus(null, 2500)).toBe(\"not_recorded\");\n    expect(metricStatus(1000, 2500)).toBe(\"tracked\");\n    expect(metricStatus(2500, 2500)).toBe(\"goal_achieved\");\n  });\n  it(\"sums a day, and returns null for a day with no records\", () => {\n    const records = [rec(\"2026-10-13\", 250), rec(\"2026-10-13\", 500), rec(\"2026-10-12\", 300)];\n    expect(dayTotal(records, \"water\", \"2026-10-13\")).toBe(750);\n    expect(dayTotal(records, \"water\", \"2026-10-11\")).toBeNull();\n  });\n  it(\"averages recorded days only — missing days are not zeros\", () => {\n    expect(averageRecorded([2000, null, 3000, null])).toBe(2500);\n    expect(averageRecorded([null, null])).toBeNull();\n  });\n  it(\"counts days the goal was met\", () => {\n    expect(daysGoalMet([2500, 1000, null, 3000], 2500)).toBe(2);\n  });\n  it(\"streak ignores an unfinished today but breaks on a missed day\", () => {\n    expect(goalStreak([2500, 2600, 2500, 800], 2500)).toBe(3);\n    expect(goalStreak([2500, null, 2500, 2500], 2500)).toBe(2);\n  });\n});\n\ndescribe(\"dates\", () => {\n  it(\"uses the man's timezone: 23:30 UTC is already tomorrow in Dar es Salaam\", () => {\n    const d = new Date(\"2026-10-13T23:30:00Z\");\n    expect(dateKey(d, \"UTC\")).toBe(\"2026-10-13\");\n    expect(dateKey(d, \"Africa/Dar_es_Salaam\")).toBe(\"2026-10-14\");\n  });\n  it(\"shifts across month and year ends\", () => {\n    expect(shiftKey(\"2026-01-01\", -1)).toBe(\"2025-12-31\");\n    expect(shiftKey(\"2026-02-28\", 1)).toBe(\"2026-03-01\");\n  });\n  it(\"gives the last 7 days, oldest first, ending today\", () => {\n    const keys = lastNDays(7, new Date(\"2026-10-13T09:00:00Z\"), \"Africa/Dar_es_Salaam\");\n    expect(keys).toEqual([\n      \"2026-10-07\", \"2026-10-08\", \"2026-10-09\", \"2026-10-10\", \"2026-10-11\", \"2026-10-12\", \"2026-10-13\",\n    ]);\n  });\n});\n\ndescribe(\"sleep and check-ins\", () => {\n  it(\"works out sleep across midnight: 22:30 → 06:15 = 7h 45m\", () => {\n    expect(sleepMinutes(\"22:30\", \"06:15\")).toBe(465);\n    expect(sleepMinutes(\"01:00\", \"07:30\")).toBe(390);\n  });\n  it(\"rejects bad or equal times\", () => {\n    expect(sleepMinutes(\"25:00\", \"06:00\")).toBeNull();\n    expect(sleepMinutes(\"22:00\", \"22:00\")).toBeNull();\n    expect(sleepMinutes(\"\", \"06:00\")).toBeNull();\n  });\n  it(\"uses the latest answer of the day\", () => {\n    const a = { ...rec(\"2026-10-13\", 2), metric: \"energy\" as const, updatedAt: \"2026-10-13T07:00:00Z\" };\n    const b = { ...rec(\"2026-10-13\", 4), id: \"b\", metric: \"energy\" as const, updatedAt: \"2026-10-13T09:00:00Z\" };\n    expect(dayLatest([a, b], \"energy\", \"2026-10-13\")?.value).toBe(4);\n    expect(dayLatest([a, b], \"energy\", \"2026-10-12\")).toBeNull();\n  });\n  it(\"compares periods only when both have data\", () => {\n    expect(periodChange(3.6, 2.8)).toBeCloseTo(0.8);\n    expect(periodChange(3.6, null)).toBeNull();\n  });\n});\n",
  "src/lib/progress/format.ts": "// How numbers are shown to the man.\n\nexport const litres = (ml: number) =>\n  `${(ml / 1000).toLocaleString(\"en\", { maximumFractionDigits: 2 })} L`;\n\n/** 440 → \"7h 20m\" */\nexport const duration = (min: number) => {\n  const h = Math.floor(min / 60);\n  const m = Math.round(min % 60);\n  return m === 0 ? `${h}h` : h === 0 ? `${m}m` : `${h}h ${m}m`;\n};\n\n/** 3.6 → \"3.6\", 4 → \"4\" */\nexport const score = (n: number) => n.toLocaleString(\"en\", { maximumFractionDigits: 1 });\n\n/** +0.6 / −0.3, with a real minus sign */\nexport const signed = (n: number, fmt: (v: number) => string = score) =>\n  n > 0 ? `+${fmt(n)}` : n < 0 ? `−${fmt(Math.abs(n))}` : \"no change\";\n\nexport const RATING_LABELS = [\"Very low\", \"Low\", \"Okay\", \"Good\", \"Great\"] as const;\n",
  "src/lib/progress/store.ts": "\"use client\";\n\n// Saves progress records and goals.\n// NOW: on the phone (localStorage) so it works before sign-up.\n// LATER: this file is swapped for Supabase — the screens don't change.\n\nimport { useSyncExternalStore } from \"react\";\nimport { dateKey } from \"./dates\";\nimport type { Goal, MetricType, RecordMeta, RecordSource, TrackingRecord, Unit } from \"./types\";\n\nconst KEY = \"ms_progress_v1\";\n\ntype DB = { records: TrackingRecord[]; goals: Goal[] };\nexport type ProgressState = DB & { ready: boolean };\n\n// Starting goals — the man can change them.\nconst DEFAULT_GOALS: Goal[] = [\n  { metric: \"water\", target: 2500, unit: \"ml\", period: \"day\", direction: \"increase\", updatedAt: \"\" },\n  { metric: \"sleep\", target: 420, unit: \"min\", period: \"day\", direction: \"increase\", updatedAt: \"\" },\n];\n\n/** Adds any default goal the saved data doesn't have yet (e.g. after a new tracker is added). */\nfunction withDefaults(goals: Goal[]): Goal[] {\n  const missing = DEFAULT_GOALS.filter((d) => !goals.some((g) => g.metric === d.metric));\n  return [...goals, ...missing];\n}\n\nconst SERVER_STATE: ProgressState = { records: [], goals: DEFAULT_GOALS, ready: false };\nlet cache: ProgressState | null = null;\nconst listeners = new Set<() => void>();\n\nfunction load(): ProgressState {\n  if (cache) return cache;\n  let db: DB = { records: [], goals: DEFAULT_GOALS };\n  try {\n    const raw = localStorage.getItem(KEY);\n    if (raw) {\n      const parsed = JSON.parse(raw) as Partial<DB>;\n      db = {\n        records: Array.isArray(parsed.records) ? parsed.records : [],\n        goals: withDefaults(Array.isArray(parsed.goals) ? parsed.goals : []),\n      };\n    }\n  } catch {\n    // Storage blocked or corrupted — start empty rather than crash\n  }\n  cache = { ...db, ready: true };\n  return cache;\n}\n\nfunction save(next: DB) {\n  cache = { ...next, ready: true };\n  try {\n    localStorage.setItem(KEY, JSON.stringify(next));\n  } catch {\n    // Storage full or blocked — keep working in memory for this visit\n  }\n  listeners.forEach((l) => l());\n}\n\nfunction newId() {\n  return typeof crypto !== \"undefined\" && \"randomUUID\" in crypto\n    ? crypto.randomUUID()\n    : `${Date.now()}-${Math.random().toString(36).slice(2)}`;\n}\n\n/** React hook: the current records and goals; re-renders when they change. */\nexport function useProgress(): ProgressState {\n  return useSyncExternalStore(\n    (cb) => {\n      listeners.add(cb);\n      return () => listeners.delete(cb);\n    },\n    load,\n    () => SERVER_STATE,\n  );\n}\n\ntype NewRecord = {\n  metric: MetricType;\n  value: number;\n  unit: Unit;\n  source: RecordSource;\n  recordedAt?: Date;\n  note?: string;\n  meta?: RecordMeta;\n};\n\nfunction makeRecord(input: NewRecord): TrackingRecord {\n  const at = input.recordedAt ?? new Date();\n  const now = new Date().toISOString();\n  return {\n    id: newId(),\n    userId: \"local\",\n    metric: input.metric,\n    value: Math.round(input.value * 10) / 10,\n    unit: input.unit,\n    source: input.source,\n    recordedAt: at.toISOString(),\n    localDate: dateKey(at),\n    note: input.note,\n    meta: input.meta,\n    createdAt: now,\n    updatedAt: now,\n  };\n}\n\nexport const progressStore = {\n  addRecord(input: NewRecord): TrackingRecord | null {\n    if (!Number.isFinite(input.value) || input.value <= 0) return null;\n    const record = makeRecord(input);\n    const db = load();\n    save({ records: [...db.records, record], goals: db.goals });\n    return record;\n  },\n\n  updateRecord(id: string, value: number, meta?: RecordMeta) {\n    if (!Number.isFinite(value) || value <= 0) return;\n    const db = load();\n    save({\n      records: db.records.map((r) =>\n        r.id === id\n          ? {\n              ...r,\n              value: Math.round(value * 10) / 10,\n              meta: meta ?? r.meta,\n              source: \"manual\",\n              updatedAt: new Date().toISOString(),\n            }\n          : r,\n      ),\n      goals: db.goals,\n    });\n  },\n\n  deleteRecord(id: string): TrackingRecord | undefined {\n    const db = load();\n    const removed = db.records.find((r) => r.id === id);\n    save({ records: db.records.filter((r) => r.id !== id), goals: db.goals });\n    return removed;\n  },\n\n  /** One value per day (e.g. today's energy rating): replaces today's earlier answer. */\n  setDailyValue(input: NewRecord) {\n    if (!Number.isFinite(input.value) || input.value <= 0) return;\n    const record = makeRecord(input);\n    const db = load();\n    save({\n      records: [\n        ...db.records.filter((r) => !(r.metric === record.metric && r.localDate === record.localDate)),\n        record,\n      ],\n      goals: db.goals,\n    });\n  },\n\n  setGoal(metric: MetricType, target: number, unit: Unit) {\n    if (!Number.isFinite(target) || target <= 0) return;\n    const db = load();\n    const now = new Date().toISOString();\n    const exists = db.goals.some((g) => g.metric === metric);\n    save({\n      records: db.records,\n      goals: exists\n        ? db.goals.map((g) => (g.metric === metric ? { ...g, target: Math.round(target), updatedAt: now } : g))\n        : [...db.goals, { metric, target: Math.round(target), unit, period: \"day\", direction: \"increase\", updatedAt: now }],\n    });\n  },\n};\n\nexport function goalFor(goals: Goal[], metric: MetricType): Goal | undefined {\n  return goals.find((g) => g.metric === metric);\n}\n",
  "src/components/progress/DayBars.tsx": "import { weekdayLetter } from \"@/lib/progress/dates\";\n\n/**\n * Bars per day from real records.\n * - Recorded day: solid bar, height = value compared with the goal\n * - Goal reached: dark green\n * - Nothing recorded: short striped stub (missing is NOT shown as zero)\n */\nexport default function DayBars({\n  keys,\n  values,\n  target,\n  format,\n  scaleMax,\n  compact = false,\n}: {\n  keys: string[];\n  values: (number | null)[];\n  target: number | null;\n  format: (v: number) => string;\n  /** Fixed top of the scale (e.g. 5 for ratings). Otherwise the goal or the highest value. */\n  scaleMax?: number;\n  /** Shorter chart without the colour key. */\n  compact?: boolean;\n}) {\n  const max = scaleMax ?? Math.max(target ?? 0, ...values.map((v) => v ?? 0), 1);\n  const dense = keys.length > 10;\n\n  return (\n    <div>\n      <div className={`flex items-end ${compact ? \"h-20\" : \"h-32\"} ${dense ? \"gap-[3px]\" : \"gap-2\"}`}>\n        {keys.map((k, i) => {\n          const v = values[i];\n          const met = v !== null && target !== null && v >= target;\n          return (\n            <div\n              key={k}\n              className=\"flex h-full flex-1 flex-col items-center justify-end\"\n              title={v === null ? `${k}: not recorded` : `${k}: ${format(v)}`}\n            >\n              {v === null ? (\n                <div className=\"hatch h-[18%] w-full rounded-full\" />\n              ) : (\n                <div\n                  className={`grow-bar w-full rounded-full ${met ? \"bg-forest-deep\" : \"bg-mint-strong\"}`}\n                  style={{\n                    height: `${Math.max((v / max) * 100, 6)}%`,\n                    animationDelay: `${Math.min(i * 40, 600)}ms`,\n                  }}\n                />\n              )}\n            </div>\n          );\n        })}\n      </div>\n      {!dense && (\n        <div className=\"mt-2 flex gap-2\">\n          {keys.map((k) => (\n            <span key={k} className=\"flex-1 text-center text-[11px] text-ink-soft\">\n              {weekdayLetter(k)}\n            </span>\n          ))}\n        </div>\n      )}\n      {!compact && (\n      <div className=\"mt-3 flex flex-wrap gap-x-4 gap-y-1 text-[11px] text-ink-soft\">\n        <span className=\"flex items-center gap-1.5\"><i className=\"h-2 w-2 rounded-full bg-forest-deep\" /> Goal reached</span>\n        <span className=\"flex items-center gap-1.5\"><i className=\"h-2 w-2 rounded-full bg-mint-strong\" /> Recorded</span>\n        <span className=\"flex items-center gap-1.5\"><i className=\"hatch h-2 w-2 rounded-full\" /> Not recorded</span>\n      </div>\n      )}\n    </div>\n  );\n}\n",
  "src/components/progress/StatusBadge.tsx": "import type { MetricStatus } from \"@/lib/progress/types\";\n\nconst STYLES: Record<MetricStatus, { text: string; cls: string }> = {\n  not_recorded: { text: \"Not yet recorded\", cls: \"bg-bg text-ink-soft ring-1 ring-line\" },\n  tracked: { text: \"Tracked\", cls: \"bg-mint text-forest\" },\n  goal_achieved: { text: \"Goal reached\", cls: \"bg-forest-deep text-white\" },\n};\n\nexport default function StatusBadge({ status, text }: { status: MetricStatus; text?: string }) {\n  const s = STYLES[status];\n  return <span className={`rounded-full px-2.5 py-1 text-[11px] font-semibold ${s.cls}`}>{text ?? s.text}</span>;\n}\n",
  "src/components/progress/HydrationCard.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport { Droplet, GlassWater, Milk, Plus, Pencil } from \"lucide-react\";\nimport ProgressBar from \"./ProgressBar\";\nimport DayBars from \"./DayBars\";\nimport StatusBadge from \"./StatusBadge\";\nimport Sheet from \"@/components/motion/Sheet\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { goalFor, progressStore, useProgress } from \"@/lib/progress/store\";\nimport { dateKey, lastNDays } from \"@/lib/progress/dates\";\nimport {\n  averageRecorded,\n  dayTotal,\n  dayTotals,\n  daysGoalMet,\n  goalStreak,\n  metricStatus,\n  targetProgress,\n} from \"@/lib/progress/calc\";\nimport { litres } from \"@/lib/progress/format\";\nimport type { Period, RecordSource, TrackingRecord } from \"@/lib/progress/types\";\n\nconst QUICK = [\n  { ml: 250, label: \"Glass\", Icon: GlassWater },\n  { ml: 500, label: \"Bottle\", Icon: Milk },\n];\n\nconst SOURCE_LABEL: Record<RecordSource, string> = {\n  manual: \"Entered\",\n  quick_add: \"Quick add\",\n  ai_estimate: \"AI estimate\",\n  device_sync: \"Synced\",\n  calculated: \"Calculated\",\n};\n\ntype SheetMode = { kind: \"custom\" } | { kind: \"edit\"; record: TrackingRecord } | { kind: \"goal\" } | null;\n\nexport default function HydrationCard({ period }: { period: Period }) {\n  const { records, goals, ready } = useProgress();\n  const showToast = useToast();\n  const [sheet, setSheet] = useState<SheetMode>(null);\n  const [input, setInput] = useState(\"\");\n  const [error, setError] = useState(\"\");\n\n  const goal = goalFor(goals, \"water\")?.target ?? null;\n  const today = dateKey(new Date());\n  const todayTotal = dayTotal(records, \"water\", today);\n  const status = metricStatus(todayTotal, goal);\n  const pct = targetProgress(todayTotal, goal);\n\n  const keys = lastNDays(period === 1 ? 7 : period);\n  const totals = dayTotals(records, \"water\", keys);\n  const recordedDays = totals.filter((v) => v !== null).length;\n  const avg = averageRecorded(totals);\n  const met = daysGoalMet(totals, goal);\n  const streak = goalStreak(dayTotals(records, \"water\", lastNDays(90)), goal);\n\n  const todayEntries = records\n    .filter((r) => r.metric === \"water\" && r.localDate === today)\n    .sort((a, b) => b.recordedAt.localeCompare(a.recordedAt));\n\n  function quickAdd(ml: number) {\n    progressStore.addRecord({ metric: \"water\", value: ml, unit: \"ml\", source: \"quick_add\" });\n    showToast(`+${ml} ml water logged`);\n  }\n\n  function openSheet(mode: SheetMode) {\n    setError(\"\");\n    setInput(\n      mode?.kind === \"edit\" ? String(mode.record.value) : mode?.kind === \"goal\" && goal ? String(goal) : \"\",\n    );\n    setSheet(mode);\n  }\n\n  function submit() {\n    const n = Number(input);\n    const max = sheet?.kind === \"goal\" ? 10000 : 5000;\n    if (!input.trim() || !Number.isFinite(n) || n <= 0) return setError(\"Enter an amount in ml, like 300\");\n    if (n > max) return setError(`That's more than ${litres(max)}. Check the amount.`);\n    if (sheet?.kind === \"custom\") {\n      progressStore.addRecord({ metric: \"water\", value: n, unit: \"ml\", source: \"manual\" });\n      showToast(`+${Math.round(n)} ml water logged`);\n    } else if (sheet?.kind === \"edit\") {\n      progressStore.updateRecord(sheet.record.id, n);\n      showToast(\"Entry updated\");\n    } else if (sheet?.kind === \"goal\") {\n      progressStore.setGoal(\"water\", n, \"ml\");\n      showToast(`Daily goal set to ${litres(n)}`);\n    }\n    setSheet(null);\n  }\n\n  function remove(record: TrackingRecord) {\n    progressStore.deleteRecord(record.id);\n    setSheet(null);\n    showToast(`Removed ${record.value} ml`);\n  }\n\n  if (!ready) {\n    return <div className=\"h-64 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />;\n  }\n\n  return (\n    <>\n      <section className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n        {/* Header */}\n        <div className=\"flex items-center justify-between\">\n          <div className=\"flex items-center gap-2\">\n            <span className=\"flex h-9 w-9 items-center justify-center rounded-xl bg-mint text-forest\">\n              <Droplet size={18} />\n            </span>\n            <div>\n              <p className=\"font-semibold\">Water</p>\n              <button onClick={() => openSheet({ kind: \"goal\" })} className=\"flex items-center gap-1 text-xs text-ink-soft\">\n                Daily goal {goal ? litres(goal) : \"not set\"} <Pencil size={11} />\n              </button>\n            </div>\n          </div>\n          <StatusBadge status={status} />\n        </div>\n\n        {period === 1 ? (\n          <>\n            {/* Today */}\n            <p className=\"mt-5 text-3xl font-bold\">\n              {todayTotal === null ? (\n                <span className=\"text-ink-soft\">—</span>\n              ) : (\n                litres(todayTotal)\n              )}\n              <span className=\"text-base font-medium text-ink-soft\"> / {goal ? litres(goal) : \"—\"}</span>\n            </p>\n            <div className=\"mt-3\">\n              <ProgressBar percent={pct} status={status} label=\"Water today\" />\n            </div>\n            <p className=\"mt-2 text-xs text-ink-soft\">\n              {status === \"not_recorded\"\n                ? \"Nothing recorded yet today.\"\n                : status === \"goal_achieved\"\n                  ? \"Goal reached today. Well done.\"\n                  : `${Math.round(pct ?? 0)}% · ${litres(Math.max((goal ?? 0) - (todayTotal ?? 0), 0))} to go`}\n            </p>\n\n            {/* Quick add */}\n            <div className=\"mt-4 grid grid-cols-3 gap-2\">\n              {QUICK.map(({ ml, label, Icon }) => (\n                <button\n                  key={ml}\n                  onClick={() => quickAdd(ml)}\n                  className=\"flex flex-col items-center gap-1 rounded-2xl bg-mint/60 py-3 text-forest transition-transform active:scale-[0.96]\"\n                >\n                  <Icon size={18} />\n                  <span className=\"text-xs font-semibold\">+{ml} ml</span>\n                  <span className=\"text-[10px] text-ink-soft\">{label}</span>\n                </button>\n              ))}\n              <button\n                onClick={() => openSheet({ kind: \"custom\" })}\n                className=\"flex flex-col items-center gap-1 rounded-2xl py-3 ring-1 ring-line transition-transform active:scale-[0.96]\"\n              >\n                <Plus size={18} />\n                <span className=\"text-xs font-semibold\">Custom</span>\n                <span className=\"text-[10px] text-ink-soft\">Any amount</span>\n              </button>\n            </div>\n\n            {/* Today's entries */}\n            {todayEntries.length > 0 && (\n              <ul className=\"mt-4 divide-y divide-line border-t border-line\">\n                {todayEntries.map((r) => (\n                  <li key={r.id}>\n                    <button\n                      onClick={() => openSheet({ kind: \"edit\", record: r })}\n                      className=\"flex w-full items-center justify-between py-2.5 text-left text-sm\"\n                    >\n                      <span>\n                        {r.value} ml\n                        <span className=\"ml-2 text-[11px] text-ink-soft\">{SOURCE_LABEL[r.source]}</span>\n                      </span>\n                      <span className=\"text-xs text-ink-soft\">\n                        {new Date(r.recordedAt).toLocaleTimeString([], { hour: \"2-digit\", minute: \"2-digit\" })}\n                      </span>\n                    </button>\n                  </li>\n                ))}\n              </ul>\n            )}\n          </>\n        ) : (\n          <>\n            {/* Period summary */}\n            <div className=\"mt-5 grid grid-cols-3 gap-2 text-center\">\n              <Stat label=\"Daily average\" value={avg === null ? \"—\" : litres(Math.round(avg))} hint=\"recorded days\" />\n              <Stat label=\"Goal reached\" value={`${met}`} hint={`of ${recordedDays} recorded`} />\n              <Stat label=\"Streak\" value={`${streak}`} hint={streak === 1 ? \"day\" : \"days\"} />\n            </div>\n            {recordedDays === 0 && (\n              <p className=\"mt-3 text-xs text-ink-soft\">No water recorded in the last {period} days.</p>\n            )}\n          </>\n        )}\n\n        {/* Chart */}\n        <div className=\"mt-5 border-t border-line pt-4\">\n          <p className=\"mb-3 text-xs font-medium text-ink-soft\">\n            {period === 1 ? \"Last 7 days\" : `Last ${period} days`}\n          </p>\n          <DayBars keys={keys} values={totals} target={goal} format={litres} />\n        </div>\n      </section>\n\n      {/* Add / edit / goal sheet */}\n      <Sheet\n        open={sheet !== null}\n        onClose={() => setSheet(null)}\n        title={sheet?.kind === \"goal\" ? \"Daily water goal\" : sheet?.kind === \"edit\" ? \"Edit entry\" : \"Add water\"}\n      >\n        <label htmlFor=\"water-ml\" className=\"text-xs text-ink-soft\">\n          Amount in ml\n        </label>\n        <input\n          id=\"water-ml\"\n          autoFocus\n          inputMode=\"numeric\"\n          value={input}\n          onChange={(e) => {\n            setInput(e.target.value.replace(/[^\\d.]/g, \"\"));\n            setError(\"\");\n          }}\n          onKeyDown={(e) => e.key === \"Enter\" && submit()}\n          placeholder={sheet?.kind === \"goal\" ? \"2500\" : \"300\"}\n          className={`mt-1 w-full rounded-2xl px-4 py-3 text-sm outline-none ring-1 focus:ring-2 ${\n            error ? \"ring-red-500 focus:ring-red-500\" : \"ring-line focus:ring-forest\"\n          }`}\n        />\n        {error && <p className=\"mt-1.5 text-xs text-red-600\">{error}</p>}\n        {sheet?.kind === \"goal\" && (\n          <p className=\"mt-2 text-xs text-ink-soft\">A common starting point is 2,000–3,000 ml. Choose what suits you.</p>\n        )}\n        <div className=\"mt-5 flex items-center justify-between gap-2\">\n          {sheet?.kind === \"edit\" ? (\n            <button onClick={() => remove(sheet.record)} className=\"text-sm font-semibold text-red-600\">\n              Delete\n            </button>\n          ) : (\n            <span />\n          )}\n          <div className=\"flex gap-2\">\n            <button onClick={() => setSheet(null)} className=\"rounded-full px-5 py-2.5 text-sm font-semibold ring-1 ring-line\">\n              Cancel\n            </button>\n            <button onClick={submit} className=\"rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n              Save\n            </button>\n          </div>\n        </div>\n      </Sheet>\n    </>\n  );\n}\n\nfunction Stat({ label, value, hint }: { label: string; value: string; hint: string }) {\n  return (\n    <div className=\"rounded-2xl bg-bg p-3\">\n      <p className=\"text-lg font-bold\">{value}</p>\n      <p className=\"text-[11px] font-medium\">{label}</p>\n      <p className=\"text-[10px] text-ink-soft\">{hint}</p>\n    </div>\n  );\n}\n",
  "src/components/progress/SleepCard.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport { Moon, Pencil } from \"lucide-react\";\nimport ProgressBar from \"./ProgressBar\";\nimport DayBars from \"./DayBars\";\nimport StatusBadge from \"./StatusBadge\";\nimport Sheet from \"@/components/motion/Sheet\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { goalFor, progressStore, useProgress } from \"@/lib/progress/store\";\nimport { dateKey, lastNDays } from \"@/lib/progress/dates\";\nimport { averageRecorded, dayLatest, dayLatestValues, daysGoalMet, metricStatus, sleepMinutes, targetProgress } from \"@/lib/progress/calc\";\nimport { duration, RATING_LABELS, score } from \"@/lib/progress/format\";\nimport type { Period } from \"@/lib/progress/types\";\n\ntype Mode = \"log\" | \"goal\" | null;\n\nexport default function SleepCard({ period }: { period: Period }) {\n  const { records, goals, ready } = useProgress();\n  const showToast = useToast();\n  const [mode, setMode] = useState<Mode>(null);\n  const [bed, setBed] = useState(\"22:30\");\n  const [wake, setWake] = useState(\"06:30\");\n  const [quality, setQuality] = useState<number | null>(null);\n  const [goalHours, setGoalHours] = useState(\"\");\n  const [error, setError] = useState(\"\");\n\n  const goal = goalFor(goals, \"sleep\")?.target ?? null;\n  const today = dateKey(new Date());\n  const lastNight = dayLatest(records, \"sleep\", today);\n  const lastValue = lastNight?.value ?? null;\n  const status = metricStatus(lastValue, goal);\n  const pct = targetProgress(lastValue, goal);\n\n  const keys = lastNDays(period === 1 ? 7 : period);\n  const values = dayLatestValues(records, \"sleep\", keys);\n  const recorded = values.filter((v) => v !== null).length;\n  const avg = averageRecorded(values);\n  const met = daysGoalMet(values, goal);\n  const qualities = keys.map((k) => dayLatest(records, \"sleep\", k)?.meta?.quality ?? null);\n  const avgQuality = averageRecorded(qualities);\n\n  const preview = sleepMinutes(bed, wake);\n\n  function openLog() {\n    setError(\"\");\n    setBed(lastNight?.meta?.bedtime ?? \"22:30\");\n    setWake(lastNight?.meta?.wakeTime ?? \"06:30\");\n    setQuality(lastNight?.meta?.quality ?? null);\n    setMode(\"log\");\n  }\n\n  function openGoal() {\n    setError(\"\");\n    setGoalHours(goal ? String(goal / 60) : \"\");\n    setMode(\"goal\");\n  }\n\n  function saveLog() {\n    const mins = sleepMinutes(bed, wake);\n    if (mins === null) return setError(\"Choose a bedtime and a wake-up time.\");\n    if (mins < 60 || mins > 960) return setError(\"That's under 1 hour or over 16 hours. Check the times.\");\n    const meta = { bedtime: bed, wakeTime: wake, quality: quality ?? undefined };\n    if (lastNight) {\n      progressStore.updateRecord(lastNight.id, mins, meta);\n      showToast(\"Sleep updated\");\n    } else {\n      progressStore.addRecord({ metric: \"sleep\", value: mins, unit: \"min\", source: \"manual\", meta });\n      showToast(`${duration(mins)} of sleep logged`);\n    }\n    setMode(null);\n  }\n\n  function saveGoal() {\n    const h = Number(goalHours);\n    if (!goalHours.trim() || !Number.isFinite(h) || h < 3 || h > 12) return setError(\"Enter hours between 3 and 12, like 7.5\");\n    progressStore.setGoal(\"sleep\", h * 60, \"min\");\n    showToast(`Sleep goal set to ${duration(h * 60)}`);\n    setMode(null);\n  }\n\n  function remove() {\n    if (!lastNight) return;\n    progressStore.deleteRecord(lastNight.id);\n    setMode(null);\n    showToast(\"Sleep entry removed\");\n  }\n\n  if (!ready) return <div className=\"h-56 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />;\n\n  return (\n    <>\n      <section className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n        <div className=\"flex items-center justify-between\">\n          <div className=\"flex items-center gap-2\">\n            <span className=\"flex h-9 w-9 items-center justify-center rounded-xl bg-mint text-forest\">\n              <Moon size={18} />\n            </span>\n            <div>\n              <p className=\"font-semibold\">Sleep</p>\n              <button onClick={openGoal} className=\"flex items-center gap-1 text-xs text-ink-soft\">\n                Goal {goal ? duration(goal) : \"not set\"} <Pencil size={11} />\n              </button>\n            </div>\n          </div>\n          <StatusBadge status={status} />\n        </div>\n\n        {period === 1 ? (\n          <>\n            <p className=\"mt-5 text-xs font-medium text-ink-soft\">Last night</p>\n            <p className=\"text-3xl font-bold\">\n              {lastValue === null ? <span className=\"text-ink-soft\">—</span> : duration(lastValue)}\n              <span className=\"text-base font-medium text-ink-soft\"> / {goal ? duration(goal) : \"—\"}</span>\n            </p>\n            <div className=\"mt-3\">\n              <ProgressBar percent={pct} status={status} label=\"Sleep last night\" />\n            </div>\n            {lastNight ? (\n              <p className=\"mt-2 text-xs text-ink-soft\">\n                {lastNight.meta?.bedtime} → {lastNight.meta?.wakeTime}\n                {lastNight.meta?.quality ? ` · Quality: ${RATING_LABELS[lastNight.meta.quality - 1]}` : \"\"}\n              </p>\n            ) : (\n              <p className=\"mt-2 text-xs text-ink-soft\">Not logged yet for last night.</p>\n            )}\n            <button\n              onClick={openLog}\n              className=\"mt-4 w-full rounded-full bg-forest py-3 text-sm font-semibold text-white transition-transform active:scale-[0.98]\"\n            >\n              {lastNight ? \"Edit last night\" : \"Log last night\"}\n            </button>\n          </>\n        ) : (\n          <div className=\"mt-5 grid grid-cols-3 gap-2 text-center\">\n            <Stat label=\"Average\" value={avg === null ? \"—\" : duration(avg)} hint=\"recorded nights\" />\n            <Stat label=\"Goal reached\" value={`${met}`} hint={`of ${recorded} nights`} />\n            <Stat label=\"Quality\" value={avgQuality === null ? \"—\" : `${score(avgQuality)}/5`} hint=\"average\" />\n          </div>\n        )}\n\n        <div className=\"mt-5 border-t border-line pt-4\">\n          <p className=\"mb-3 text-xs font-medium text-ink-soft\">{period === 1 ? \"Last 7 nights\" : `Last ${period} nights`}</p>\n          <DayBars keys={keys} values={values} target={goal} format={duration} />\n        </div>\n      </section>\n\n      <Sheet open={mode !== null} onClose={() => setMode(null)} title={mode === \"goal\" ? \"Sleep goal\" : \"Last night's sleep\"}>\n        {mode === \"goal\" ? (\n          <>\n            <label htmlFor=\"sleep-goal\" className=\"text-xs text-ink-soft\">Hours per night</label>\n            <input\n              id=\"sleep-goal\"\n              autoFocus\n              inputMode=\"decimal\"\n              value={goalHours}\n              onChange={(e) => {\n                setGoalHours(e.target.value.replace(/[^\\d.]/g, \"\"));\n                setError(\"\");\n              }}\n              placeholder=\"7\"\n              className={`mt-1 w-full rounded-2xl px-4 py-3 text-sm outline-none ring-1 focus:ring-2 ${error ? \"ring-red-500\" : \"ring-line focus:ring-forest\"}`}\n            />\n            <p className=\"mt-2 text-xs text-ink-soft\">Most adults do well with 7–9 hours. Choose what suits you.</p>\n          </>\n        ) : (\n          <>\n            <div className=\"grid grid-cols-2 gap-3\">\n              <label className=\"text-xs text-ink-soft\">\n                Went to bed\n                <input\n                  type=\"time\"\n                  value={bed}\n                  onChange={(e) => {\n                    setBed(e.target.value);\n                    setError(\"\");\n                  }}\n                  className=\"mt-1 w-full rounded-2xl px-3 py-3 text-sm text-ink outline-none ring-1 ring-line focus:ring-2 focus:ring-forest\"\n                />\n              </label>\n              <label className=\"text-xs text-ink-soft\">\n                Woke up\n                <input\n                  type=\"time\"\n                  value={wake}\n                  onChange={(e) => {\n                    setWake(e.target.value);\n                    setError(\"\");\n                  }}\n                  className=\"mt-1 w-full rounded-2xl px-3 py-3 text-sm text-ink outline-none ring-1 ring-line focus:ring-2 focus:ring-forest\"\n                />\n              </label>\n            </div>\n            <p className=\"mt-2 text-sm font-semibold text-forest\">{preview ? `${duration(preview)} of sleep` : \"—\"}</p>\n            <p className=\"mt-4 text-xs text-ink-soft\">How well did you sleep? (optional)</p>\n            <div className=\"mt-2 grid grid-cols-5 gap-1.5\">\n              {RATING_LABELS.map((label, i) => (\n                <button\n                  key={label}\n                  onClick={() => setQuality(quality === i + 1 ? null : i + 1)}\n                  className={`rounded-xl py-2 text-[10px] font-semibold transition-colors ${\n                    quality === i + 1 ? \"bg-forest text-white\" : \"ring-1 ring-line\"\n                  }`}\n                >\n                  {label}\n                </button>\n              ))}\n            </div>\n          </>\n        )}\n        {error && <p className=\"mt-2 text-xs text-red-600\">{error}</p>}\n        <div className=\"mt-5 flex items-center justify-between gap-2\">\n          {mode === \"log\" && lastNight ? (\n            <button onClick={remove} className=\"text-sm font-semibold text-red-600\">Delete</button>\n          ) : (\n            <span />\n          )}\n          <div className=\"flex gap-2\">\n            <button onClick={() => setMode(null)} className=\"rounded-full px-5 py-2.5 text-sm font-semibold ring-1 ring-line\">\n              Cancel\n            </button>\n            <button onClick={mode === \"goal\" ? saveGoal : saveLog} className=\"rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n              Save\n            </button>\n          </div>\n        </div>\n      </Sheet>\n    </>\n  );\n}\n\nfunction Stat({ label, value, hint }: { label: string; value: string; hint: string }) {\n  return (\n    <div className=\"rounded-2xl bg-bg p-3\">\n      <p className=\"text-lg font-bold\">{value}</p>\n      <p className=\"text-[11px] font-medium\">{label}</p>\n      <p className=\"text-[10px] text-ink-soft\">{hint}</p>\n    </div>\n  );\n}\n",
  "src/components/progress/CheckInCard.tsx": "\"use client\";\n\nimport { Smile } from \"lucide-react\";\nimport DayBars from \"./DayBars\";\nimport StatusBadge from \"./StatusBadge\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { progressStore, useProgress } from \"@/lib/progress/store\";\nimport { dateKey, lastNDays, shiftKey } from \"@/lib/progress/dates\";\nimport { averageRecorded, dayLatest, dayLatestValues, periodChange } from \"@/lib/progress/calc\";\nimport { RATING_LABELS, score, signed } from \"@/lib/progress/format\";\nimport type { Period } from \"@/lib/progress/types\";\n\nconst QUESTIONS = [\n  { metric: \"energy\", title: \"Energy\", ask: \"How is your energy today?\" },\n  { metric: \"mood\", title: \"Mood\", ask: \"How is your mood today?\" },\n] as const;\n\nexport default function CheckInCard({ period }: { period: Period }) {\n  const { records, ready } = useProgress();\n  const showToast = useToast();\n  const today = dateKey(new Date());\n\n  const answered = QUESTIONS.filter((q) => dayLatest(records, q.metric, today)).length;\n  const status = answered === 0 ? \"not_recorded\" : \"tracked\";\n  const badge = answered === 0 ? \"Not yet today\" : answered === 2 ? \"Checked in\" : \"1 of 2 answered\";\n\n  const days = period === 1 ? 7 : period;\n  const keys = lastNDays(days);\n  const prevKeys = keys.map((k) => shiftKey(k, -days));\n\n  function answer(metric: \"energy\" | \"mood\", value: number) {\n    progressStore.setDailyValue({ metric, value, unit: \"score\", source: \"manual\" });\n    showToast(`${metric === \"energy\" ? \"Energy\" : \"Mood\"}: ${RATING_LABELS[value - 1]}`);\n  }\n\n  if (!ready) return <div className=\"h-56 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />;\n\n  return (\n    <section className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n      <div className=\"flex items-center justify-between\">\n        <div className=\"flex items-center gap-2\">\n          <span className=\"flex h-9 w-9 items-center justify-center rounded-xl bg-mint text-forest\">\n            <Smile size={18} />\n          </span>\n          <div>\n            <p className=\"font-semibold\">Energy and mood</p>\n            <p className=\"text-xs text-ink-soft\">Daily check-in · 1 to 5</p>\n          </div>\n        </div>\n        <StatusBadge status={status} text={badge} />\n      </div>\n\n      {QUESTIONS.map((q) => {\n        const todayValue = dayLatest(records, q.metric, today)?.value ?? null;\n        const values = dayLatestValues(records, q.metric, keys);\n        const avg = averageRecorded(values);\n        const prevAvg = averageRecorded(dayLatestValues(records, q.metric, prevKeys));\n        const change = periodChange(avg, prevAvg);\n        const recorded = values.filter((v) => v !== null).length;\n\n        return (\n          <div key={q.metric} className=\"mt-5 border-t border-line pt-4\">\n            {period === 1 ? (\n              <>\n                <p className=\"text-sm font-medium\">{q.ask}</p>\n                <div className=\"mt-2 grid grid-cols-5 gap-1.5\" role=\"radiogroup\" aria-label={q.title}>\n                  {RATING_LABELS.map((label, i) => {\n                    const selected = todayValue === i + 1;\n                    return (\n                      <button\n                        key={label}\n                        role=\"radio\"\n                        aria-checked={selected}\n                        onClick={() => answer(q.metric, i + 1)}\n                        className={`flex flex-col items-center gap-0.5 rounded-xl py-2 transition-all active:scale-95 ${\n                          selected ? \"bg-forest text-white\" : \"ring-1 ring-line\"\n                        }`}\n                      >\n                        <span className=\"text-sm font-bold\">{i + 1}</span>\n                        <span className={`text-[9px] ${selected ? \"text-mint\" : \"text-ink-soft\"}`}>{label}</span>\n                      </button>\n                    );\n                  })}\n                </div>\n              </>\n            ) : (\n              <div className=\"flex items-end justify-between\">\n                <div>\n                  <p className=\"text-sm font-medium\">{q.title}</p>\n                  <p className=\"text-2xl font-bold\">\n                    {avg === null ? <span className=\"text-ink-soft\">—</span> : score(avg)}\n                    <span className=\"text-sm font-medium text-ink-soft\"> / 5 average</span>\n                  </p>\n                  <p className=\"text-[11px] text-ink-soft\">\n                    {recorded} of {days} days answered\n                    {change !== null && ` · ${signed(change)} vs previous ${days} days`}\n                  </p>\n                </div>\n              </div>\n            )}\n            <div className=\"mt-3\">\n              <DayBars keys={keys} values={values} target={null} scaleMax={5} format={(v) => `${v}/5`} compact />\n            </div>\n          </div>\n        );\n      })}\n\n      <p className=\"mt-4 text-[11px] text-ink-soft\">\n        These are your own ratings. They help you notice patterns over time — they are not a medical measurement.\n      </p>\n    </section>\n  );\n}\n",
  "src/app/(app)/progress/page.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport { Footprints, Utensils, Ruler, ListChecks, Lock } from \"lucide-react\";\nimport HydrationCard from \"@/components/progress/HydrationCard\";\nimport SleepCard from \"@/components/progress/SleepCard\";\nimport CheckInCard from \"@/components/progress/CheckInCard\";\nimport type { Period } from \"@/lib/progress/types\";\n\nconst PERIODS: { value: Period; label: string }[] = [\n  { value: 1, label: \"Today\" },\n  { value: 7, label: \"7 days\" },\n  { value: 30, label: \"30 days\" },\n  { value: 90, label: \"90 days\" },\n];\n\n// Trackers we will add next, one step at a time. Shown honestly as \"not set up yet\".\nconst UPCOMING = [\n  { label: \"Steps and workouts\", Icon: Footprints },\n  { label: \"Food (photo + AI estimate)\", Icon: Utensils },\n  { label: \"Weight and waist\", Icon: Ruler },\n  { label: \"Habits\", Icon: ListChecks },\n  { label: \"Private wellness\", Icon: Lock },\n];\n\nexport default function ProgressPage() {\n  const [period, setPeriod] = useState<Period>(1);\n  const todayLabel = new Date().toLocaleDateString(\"en\", { weekday: \"long\", day: \"numeric\", month: \"long\" });\n\n  return (\n    <div className=\"stagger space-y-4\">\n      {/* Header */}\n      <div>\n        <h1 className=\"text-2xl font-bold\">Progress</h1>\n        <p className=\"mt-1 text-sm text-ink-soft\" suppressHydrationWarning>\n          {todayLabel}\n        </p>\n      </div>\n\n      {/* Period filter */}\n      <div className=\"flex rounded-full bg-surface p-1 ring-1 ring-line\" role=\"tablist\" aria-label=\"Period\">\n        {PERIODS.map((p) => (\n          <button\n            key={p.value}\n            role=\"tab\"\n            aria-selected={period === p.value}\n            onClick={() => setPeriod(p.value)}\n            className={`flex-1 rounded-full py-2 text-xs font-semibold transition-colors ${\n              period === p.value ? \"bg-forest text-white\" : \"text-ink-soft\"\n            }`}\n          >\n            {p.label}\n          </button>\n        ))}\n      </div>\n\n      {/* Real trackers */}\n      <CheckInCard period={period} />\n      <HydrationCard period={period} />\n      <SleepCard period={period} />\n\n      {/* Coming next */}\n      <section className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n        <p className=\"font-semibold\">More trackers</p>\n        <p className=\"text-xs text-ink-soft\">Being added step by step</p>\n        <ul className=\"mt-3 divide-y divide-line\">\n          {UPCOMING.map(({ label, Icon }) => (\n            <li key={label} className=\"flex items-center justify-between py-2.5 text-sm\">\n              <span className=\"flex items-center gap-3\">\n                <Icon size={16} className=\"text-ink-soft\" />\n                {label}\n              </span>\n              <span className=\"text-[11px] text-ink-soft\">Not set up yet</span>\n            </li>\n          ))}\n        </ul>\n      </section>\n\n      <p className=\"px-2 text-center text-[11px] text-ink-soft\">\n        Saved on this phone for now. Your records move to your account when you sign up.\n      </p>\n    </div>\n  );\n}\n"
};

for (const [path, content] of Object.entries(files)) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
  console.log("  wrote", path);
}
console.log("\nDone: " + Object.keys(files).length + " files created or updated.");
